// Realistic incoming chat payload and existing user profile state
return [{
  json: {
    user_id: "user_2tNx8...",
    conversation_id: "conv_active_session_88",
    message: "Hey Sahayam! I really love building small scripts on weekends and figuring out why things break, but lately I feel overwhelmed and unsure what direction to take.",
    messages: [
      { role: "assistant", content: "Hey! I'm Sahayam 😊 I'm so glad you're here. Think of me like a close friend who really gets you. No judgment here at all. Ready to hang out?" },
      { role: "user", content: "Yeah I'm ready! Excited to chat." },
      { role: "assistant", content: "Awesome! Before we get into anything deep, how has your day been going so far?" },
      { role: "user", content: "Hey Sahayam! I really love building small scripts on weekends and figuring out why things break, but lately I feel overwhelmed and unsure what direction to take." }
    ],
    existing_persona: {
      traits_uncovered: ["builder_instinct", "curious"],
      trait_weights: { "builder_instinct": 0.35, "curious": 0.35 },
      coverage_matrix: {
        cognitive_capabilities: 40,
        curiosity_and_enthusiasm: 50,
        habits_and_routines: 10,
        free_time_preferences: 20,
        lifestyle_and_environment: 15,
        overall_score: 27
      }
    },
    current_phase: "trust"
  }
}];

// Simulate HuggingFace all-MiniLM-L6-v2 384-dimensional dense vector calculation
const inputMsg = $input.first().json.message;
const vectorSample = [0.0421, -0.1284, 0.8931, 0.3128, -0.4512, 0.0892, 0.6519, -0.2214];

return [{
  json: {
    ...($input.first().json),
    embedding_model: "sentence-transformers/all-MiniLM-L6-v2 (HuggingFace)",
    vector_dimension: 384,
    embedding_preview: vectorSample
  }
}];

// PostgreSQL pgvector Cosine Distance Search (<=> query_embedding)
// Scoped strictly to current conversation_id
const convId = $input.first().json.conversation_id;

const retrievedMemories = [
  {
    fact: "User mentioned enjoying Python scripting and tinkering with electronics on weekends",
    category: "curiosity",
    cosine_distance: 0.124
  },
  {
    fact: "Expressed mild anxiety about career clarity and future options",
    category: "emotional_state",
    cosine_distance: 0.189
  }
];

return [{
  json: {
    ...($input.first().json),
    ltm_query_sql: `SELECT content, embedding <=> '[vector]' as dist FROM long_term_memories WHERE conversation_id = '${convId}' ORDER BY dist ASC LIMIT 3;`,
    retrieved_memories: retrievedMemories
  }
}];

// PostgreSQL pgvector Knowledge Base RAG Search over ingested prompt files:
const kbGuidance = [
  {
    prompt_file: "gems/nenu_evaru/prompts/trust_building_phase.md",
    phase: "Phase 1: Trust Building",
    guideline: "Never grill the user or rush into solutions. Validate their vulnerability first with empathetic WhatsApp friend tone.",
    cosine_distance: 0.098
  },
  {
    prompt_file: "gems/nenu_evaru/prompts/guardrails.md",
    phase: "Safety Guardrails",
    guideline: "Max 1 question per turn. Never give unsolicited career advice in early exploration.",
    cosine_distance: 0.142
  },
  {
    prompt_file: "gems/nenu_evaru/prompts/question_transformation.md",
    phase: "Hybrid Questioning",
    guideline: "Transform dry psychometric questions into conversational buddy dialogue.",
    cosine_distance: 0.165
  }
];

return [{
  json: {
    ...($input.first().json),
    kb_rag_sql: "SELECT content, embedding <=> '[vector]' as dist FROM knowledge_base_chunks ORDER BY dist ASC LIMIT 3;",
    prompt_files_referenced: [
      "gems/nenu_evaru/prompts/trust_building_phase.md",
      "gems/nenu_evaru/prompts/guardrails.md",
      "gems/nenu_evaru/prompts/question_transformation.md",
      "gems/nenu_evaru/prompts/system_prompt.md"
    ],
    knowledge_base_rules: kbGuidance
  }
}];

// Planner Node (gems/nenu_evaru/prompts/router.md & efficient_persona_engine.md)
const data = $input.first().json;
const msgCount = data.messages.filter(m => m.role === 'user').length;
const cov = data.existing_persona.coverage_matrix;

let activePhase = "trust";
if (msgCount <= 2) {
  activePhase = "trust";
} else {
  activePhase = "exploration";
}

// Heatmap evaluation per efficient_persona_engine.md
const dimensions = [
  { name: "Habits & Routines", score: cov.habits_and_routines, prompt: "gems/nenu_evaru/prompts/adult_exploration.md" },
  { name: "Lifestyle & Environment", score: cov.lifestyle_and_environment, prompt: "gems/nenu_evaru/prompts/adult_exploration.md" },
  { name: "Free Time Preferences", score: cov.free_time_preferences, prompt: "gems/nenu_evaru/prompts/childhood_exploration.md" },
  { name: "Cognitive Capabilities", score: cov.cognitive_capabilities, prompt: "gems/nenu_evaru/prompts/teenage_exploration.md" },
  { name: "Curiosity & Enthusiasm", score: cov.curiosity_and_enthusiasm, prompt: "gems/nenu_evaru/prompts/childhood_exploration.md" }
];
dimensions.sort((a, b) => a.score - b.score);
const lowestDimension = dimensions[0];

const strategicPlan = `Phase: ${activePhase.toUpperCase()}. Per router.md & trust_building_phase.md: Acknowledge builder instinct warmly ('that feeling when a script finally runs'). Validate overwhelm. Gently explore lowest-coverage area (${lowestDimension.name} @ ${lowestDimension.score}%) via ${lowestDimension.prompt}.`;

return [{
  json: {
    ...data,
    active_phase: activePhase,
    lowest_dimension: lowestDimension,
    user_exchanges: msgCount,
    strategic_plan: strategicPlan,
    governing_prompt_files: [
      "gems/nenu_evaru/prompts/router.md",
      "gems/nenu_evaru/prompts/efficient_persona_engine.md",
      "gems/nenu_evaru/prompts/guardrails.md"
    ],
    empathy_rubric: { safety: "PASS", necessity: "PASS", tone: "PASS (Warm Friend)" }
  }
}];

// Executor Agent (Ollama Llama 3.1) - Prompt: gems/nenu_evaru/prompts/trust_building_phase.md & system_prompt.md
const plan = $input.first().json.strategic_plan;
const promptApplied = `[System Instructions: gems/nenu_evaru/prompts/system_prompt.md]\n[Phase Prompt: gems/nenu_evaru/prompts/trust_building_phase.md]\n[Plan: ${plan}]\n[Tone: Casual WhatsApp friend, contractions, no robotic praise, 1 question max]`;

const generatedResponse = "Oh man, that feeling when you write a script and it finally runs with zero errors is honestly pure magic! 🙌 But I totally get how daunting it feels when you start zooming out to 'the big career picture'—it's super easy for that overwhelm to creep in. When you're in the zone building something on a Saturday, what kind of problems usually pull you in the most?";

return [{
  json: {
    ...($input.first().json),
    active_prompt_file: "gems/nenu_evaru/prompts/trust_building_phase.md",
    system_prompt_file: "gems/nenu_evaru/prompts/system_prompt.md",
    system_prompt_compiled: promptApplied,
    llm_model: "llama3.1 (temperature=0.8, presence_penalty=0.6)",
    response_text: generatedResponse
  }
}];

// Executor Agent (Ollama Llama 3.1) - Prompt: gems/nenu_evaru/prompts/adult_exploration.md & childhood_exploration.md
const generatedResponse = "I love how you naturally gravitate towards building and debugging. It says a lot about how your brain works. When you hit a roadblock during your routines, do you prefer solving it alone in deep focus, or bouncing ideas off someone else?";

return [{
  json: {
    ...($input.first().json),
    active_prompt_file: "gems/nenu_evaru/prompts/adult_exploration.md",
    system_prompt_file: "gems/nenu_evaru/prompts/system_prompt.md",
    llm_model: "llama3.1 (temperature=0.8, presence_penalty=0.6)",
    response_text: generatedResponse
  }
}];

// Extractor Agent (Ollama Qwen 2.5 Structured JSON)
// Governing Prompts: gems/nenu_evaru/prompts/trait_inference.md & persona_building.md
const userMsg = $input.first().json.message;

const extractedData = {
  new_traits: ["builder_instinct", "analytical_troubleshooter", "curiosity_driven"],
  new_facts: ["Builds scripts on weekends", "Enjoys debugging and understanding system failures"],
  dimension_hits: {
    curiosity_and_enthusiasm: 2,
    cognitive_capabilities: 1,
    habits_and_routines: 1
  }
};

return [{
  json: {
    ...($input.first().json),
    governing_prompt_files: [
      "gems/nenu_evaru/prompts/trait_inference.md",
      "gems/nenu_evaru/prompts/persona_building.md"
    ],
    extraction_llm: "qwen2.5 (temperature=0.1, structured_json)",
    extracted_persona_updates: extractedData
  }
}];

// Trait Confidence Weight Calculator (+0.25 Reinforcement per trait_inference.md)
const data = $input.first().json;
const existingWeights = data.existing_persona.trait_weights || {};
const newTraits = data.extracted_persona_updates.new_traits;

const updatedWeights = { ...existingWeights };
newTraits.forEach(trait => {
  if (updatedWeights[trait]) {
    // Reinforce existing trait up to 1.0 confidence
    updatedWeights[trait] = Math.min(1.0, parseFloat((updatedWeights[trait] + 0.25).toFixed(2)));
  } else {
    // First mention initial confidence
    updatedWeights[trait] = 0.35;
  }
});

// Update coverage matrix scores per efficient_persona_engine.md
const prevCov = data.existing_persona.coverage_matrix;
const updatedCov = {
  cognitive_capabilities: Math.min(100, prevCov.cognitive_capabilities + 15),
  curiosity_and_enthusiasm: Math.min(100, prevCov.curiosity_and_enthusiasm + 20),
  habits_and_routines: Math.min(100, prevCov.habits_and_routines + 10),
  free_time_preferences: prevCov.free_time_preferences,
  lifestyle_and_environment: prevCov.lifestyle_and_environment,
  overall_score: 0
};
updatedCov.overall_score = Math.round(
  (updatedCov.cognitive_capabilities + updatedCov.curiosity_and_enthusiasm + updatedCov.habits_and_routines + updatedCov.free_time_preferences + updatedCov.lifestyle_and_environment) / 5
);

return [{
  json: {
    ...data,
    final_persona_state: {
      traits: Object.keys(updatedWeights),
      trait_confidence_weights: updatedWeights,
      coverage_matrix: updatedCov
    }
  }
}];

// PostgreSQL Transaction Persistence Simulation
const data = $input.first().json;
const convId = data.conversation_id;
const persona = data.final_persona_state;

return [{
  json: {
    status: "SUCCESS_200",
    db_operations: [
      `UPDATE profile_states SET persona = '${JSON.stringify(persona)}' WHERE conversation_id = '${convId}';`,
      `INSERT INTO long_term_memories (conversation_id, content, embedding) VALUES ('${convId}', 'Enjoys debugging scripts', '[384-dim vector]');`,
      `INSERT INTO messages (conversation_id, role, content) VALUES ('${convId}', 'assistant', '${data.response_text.replace(/'/g, "''")}');`
    ],
    delivered_response: data.response_text,
    persona_snapshot: persona
  }
}];

// Final Client Presentation Payload
const data = $input.first().json;
return [{
  json: {
    status: "success",
    assistant_reply: data.delivered_response,
    brain_mapping_progress: `${data.persona_snapshot.coverage_matrix.overall_score}% Mapped`,
    weighted_traits: data.persona_snapshot.trait_confidence_weights,
    coverage_matrix: data.persona_snapshot.coverage_matrix,
    prompt_files_executed: [
      "gems/nenu_evaru/prompts/system_prompt.md",
      "gems/nenu_evaru/prompts/trust_building_phase.md",
      "gems/nenu_evaru/prompts/router.md",
      "gems/nenu_evaru/prompts/efficient_persona_engine.md",
      "gems/nenu_evaru/prompts/guardrails.md",
      "gems/nenu_evaru/prompts/trait_inference.md",
      "gems/nenu_evaru/prompts/persona_building.md"
    ],
    message: "Workflow executed with all prompt files active! 🚀"
  }
}];
